function setPaneAccessible(el,visible){if(!el)return;el.classList.add('workspace-pane');el.hidden=!visible;el.setAttribute('aria-hidden',String(!visible));for(const node of qa('a,button,input,select,textarea,[tabindex]',el)){if(!visible){if(!paneFocusMemory.has(node))paneFocusMemory.set(node,node.getAttribute('tabindex'));node.tabIndex=-1}else if(paneFocusMemory.has(node)){const old=paneFocusMemory.get(node);old===null?node.removeAttribute('tabindex'):node.setAttribute('tabindex',old);paneFocusMemory.delete(node)}}}
