function refreshWorkspaceContainers(){for(const selector of WORKSPACE_CONTAINERS)for(const box of qa(selector)){const members=qa('.workspace-pane',box);box.classList.toggle('workspace-container-empty',members.length>0&&!members.some(x=>!x.hidden))}}
