const API_REQUEST_KIND=Object.freeze({READ:'READ',WRITE_METADATA:'WRITE_METADATA',WRITE_CONFIG:'WRITE_CONFIG',MOTION_COMMAND:'MOTION_COMMAND'});
const API_DEFAULT_TIMEOUT_MS=5000;
function classifyApiRequest(url,method='GET'){
  const m=String(method||'GET').toUpperCase(),u=String(url||'');if(m==='GET'||m==='HEAD')return API_REQUEST_KIND.READ;
  if(/\/api\/(?:navigation\/(?:goal|cancel)|localization\/(?:initial-pose|reset-calibration)|experiment\/trial\/motion|hmi\/control|esc\/vesc\/command)/.test(u))return API_REQUEST_KIND.MOTION_COMMAND;
  if(/\/api\/(?:config\/(?:validate|apply|proposal)|imu\/calibration\/proposal|commissioning\/qualification)/.test(u))return API_REQUEST_KIND.WRITE_CONFIG;
  return API_REQUEST_KIND.WRITE_METADATA;
}
async function fetchWithTimeout(url,options={},timeoutMs=API_DEFAULT_TIMEOUT_MS){
  const controller=new AbortController(),ms=Math.max(250,+timeoutMs||API_DEFAULT_TIMEOUT_MS);let timedOut=false;
  const timer=setTimeout(()=>{timedOut=true;controller.abort()},ms);
  try{return await fetch(url,{...options,signal:controller.signal})}
  catch(e){e.agvCode=timedOut?'REQUEST_TIMEOUT':'NETWORK_ERROR';e.agvTimeoutMs=ms;throw e}
  finally{clearTimeout(timer)}
}
window.AGVFetchWithTimeout=fetchWithTimeout;
function jsonResponseFacade(ok,status,statusText,data,headers=null,requestKind=API_REQUEST_KIND.READ){return {ok,status,statusText,headers,requestKind,json:async()=>data}}
function writeLockState(){if(replayMode)return {replay_locked:true,code:'REPLAY_LOCKED',message:'REPLAY MODE aktif: semua command/write diblokir.'};if(obj('server').read_only===true)return {read_only:true,code:'READ_ONLY',message:'Server read-only: semua command/write diblokir.'};return null}
function apiFailure(code,message,{status=0,statusText='Request Error',headers=null,kind=API_REQUEST_KIND.READ,extra={}}={}){return jsonResponseFacade(false,status,statusText,{ok:false,code,message,request_kind:kind,...extra},headers,kind)}
async function apiRequest(url,{method='GET',body,timeoutMs=API_DEFAULT_TIMEOUT_MS,cache='no-store',kind,headers={},expectJson=true}={}){
  const verb=String(method||'GET').toUpperCase(),requestKind=kind||classifyApiRequest(url,verb),isWrite=!['GET','HEAD'].includes(verb);
  if(isWrite){const lock=writeLockState();if(lock)return apiFailure(lock.code,lock.message,{status:423,statusText:'Locked',kind:requestKind,extra:lock})}
  const opts={method:verb,cache,headers:{...headers}};if(body!==undefined){opts.headers['Content-Type']=opts.headers['Content-Type']||'application/json';opts.body=typeof body==='string'?body:JSON.stringify(body)}
  let r;try{r=await fetchWithTimeout(url,opts,timeoutMs)}catch(e){const code=e.agvCode||'NETWORK_ERROR',msg=code==='REQUEST_TIMEOUT'?`Request timeout ${e.agvTimeoutMs||timeoutMs} ms (${url})`:`Network request gagal (${url}): ${e.message}`;return apiFailure(code,msg,{kind:requestKind,extra:{network_error:code==='NETWORK_ERROR',timeout:code==='REQUEST_TIMEOUT',timeout_ms:e.agvTimeoutMs||timeoutMs}})}
  if(!expectJson)return r;
  let text='';try{text=await r.text()}catch(e){return apiFailure('RESPONSE_READ_ERROR',`Response tidak dapat dibaca (${url}): ${e.message}`,{status:r.status||0,statusText:r.statusText||'Read Error',headers:r.headers,kind:requestKind,extra:{response_read_error:true}})}
  let data={};if(text){try{data=JSON.parse(text)}catch(_){return apiFailure('MALFORMED_JSON',`Malformed JSON response (${url})`,{status:r.status||502,statusText:'Malformed JSON',headers:r.headers,kind:requestKind,extra:{malformed_json:true}})}}
  if(data!==null&&typeof data!=='object')return apiFailure('INVALID_JSON_SHAPE',`JSON response harus object/array (${url})`,{status:r.status||502,statusText:'Invalid JSON Shape',headers:r.headers,kind:requestKind});
  if(!r.ok&&data&&typeof data==='object'&&!Array.isArray(data)&&!data.code)data.code=`HTTP_${r.status}`;
  return jsonResponseFacade(r.ok,r.status,r.statusText,data,r.headers,requestKind)
}
function readRequest(url,opts={}){return apiRequest(url,{...opts,method:'GET',kind:API_REQUEST_KIND.READ})}
function writeRequest(url,body={},opts={}){return apiRequest(url,{...opts,method:'POST',body,kind:opts.kind||classifyApiRequest(url,'POST')})}
async function post(url,body={},silent=false){const r=await writeRequest(url,body),j=await r.json();if(!silent||!r.ok)toast(j.message||(`${r.status||'NETWORK'} ${r.statusText||'Request failed'}`),!r.ok);return j}
function trackChannelTiming(ups){const now=Date.now(),windowMs=10000;for(const [k,rawT] of Object.entries(ups||{})){const t=+rawT;if(!Number.isFinite(t))continue;let m=channelTiming.get(k);if(!m)m={last:0,dts:[],missingEvents:[]};if(!Array.isArray(m.missingEvents))m.missingEvents=[];m.missingEvents=m.missingEvents.filter(x=>now-x.at<=windowMs);if(m.last>0&&t>m.last){const dt=t-m.last,expected=CHANNEL_REGISTRY[k]?.expectedHz,nominal=expected>0?1000/expected:0,resetGap=nominal>0?Math.max(1000,nominal*10):1000;if(dt>0&&dt<=resetGap){m.dts.push(dt);while(m.dts.length>80)m.dts.shift();if(nominal>0&&dt>nominal*1.65){const count=Math.max(0,Math.round(dt/nominal)-1);if(count)m.missingEvents.push({at:now,count})}}else if(dt>resetGap){m.dts=[];m.missingEvents=[]}}if(t>m.last)m.last=t;channelTiming.set(k,m)}}
function channelDt(k){const a=channelTiming.get(k)?.dts||[];return a.length?a[a.length-1]/1000:undefined}
function channelRate(k){const a=channelTiming.get(k)?.dts||[];if(!a.length)return undefined;const recent=a.slice(-30),mean=recent.reduce((x,y)=>x+y,0)/recent.length;return mean>0?1000/mean:undefined}
function channelJitterMs(k){const a=(channelTiming.get(k)?.dts||[]).slice(-40);if(a.length<2)return undefined;const mean=a.reduce((x,y)=>x+y,0)/a.length;return Math.sqrt(a.reduce((n,v)=>n+(v-mean)**2,0)/a.length)}
function channelMissing(k){const m=channelTiming.get(k);if(!m||!Array.isArray(m.missingEvents))return 0;const now=Date.now();m.missingEvents=m.missingEvents.filter(x=>now-x.at<=10000);return m.missingEvents.reduce((sum,x)=>sum+(+x.count||0),0)}
function channelHealth(k){const meta=CHANNEL_REGISTRY[k]||{},a=age(k)*1000,r=channelRate(k),stale=meta.staleMs||1000;if(a<=stale&&(!meta.expectedHz||!Number.isFinite(r)||r>=meta.expectedHz*.55))return'LIVE';if(a<=stale*3)return'DEGRADED';return'STALE'}
function mergeSticky(prev,next){if(!prev||typeof prev!=='object'||Array.isArray(prev)||!next||typeof next!=='object'||Array.isArray(next))return next;const out={...prev};for(const [k,v] of Object.entries(next))out[k]=(v&&typeof v==='object'&&!Array.isArray(v)&&prev[k]&&typeof prev[k]==='object'&&!Array.isArray(prev[k]))?mergeSticky(prev[k],v):v;return out}
function queueRender(force=false){if(renderQueued)return;if(document.hidden&&!force)return;renderQueued=true;const delay=force?0:Math.max(0,activeRenderMs()-(performance.now()-lastRenderAt)),run=()=>requestAnimationFrame(()=>{renderQueued=false;if(document.hidden&&!force)return;lastRenderAt=performance.now();render()});delay>1?setTimeout(run,delay):run()}
function merge(delta){if(!delta||typeof delta!=='object')return;const ups=delta.__updated||{};Object.entries(delta).forEach(([k,v])=>{if(k.startsWith('__'))return;state[k]=STICKY_STREAMS.has(k)?mergeSticky(state[k],v):v});if(delta.nav_path&&pendingPlanGoalAtMs>0){lastPlanningLatencyMs=Math.max(0,Date.now()-pendingPlanGoalAtMs);pendingPlanGoalAtMs=0;if(state.nav_path&&typeof state.nav_path==='object')state.nav_path.planning_latency_ms=lastPlanningLatencyMs}else if(delta.nav_path&&Number.isFinite(lastPlanningLatencyMs)&&state.nav_path&&typeof state.nav_path==='object')state.nav_path.planning_latency_ms=lastPlanningLatencyMs;trackChannelTiming(ups);Object.assign(updated,ups);if(delta.__server_time_ms)serverDelta=Date.now()-delta.__server_time_ms;trackRuntimeEvents();window.captureVescToolState?.();if(activePage==='experiments')captureLabTelemetry?.();queueRender()}
