  if(now-lastOverviewHealthAt>=500||!lastOverviewHealthAt){lastOverviewHealthAt=now;const joy=bool(raw('connected.joystick'))?'ok':'bad',js=obj('joystick_status');healthCard('gnss',gn,getPath(obj('gnss_quality'),'sat')!=null?`${fmt(getPath(obj('gnss_quality'),'sat'),0)} sat • hAcc ${fmt(getPath(obj('gnss_quality'),'hacc_m'))}m`:'NEO-3 via F411 CDC');healthCard('imu',im,'Yahboom IMU • CP2102');healthCard('camera',ca,obj('camera_frame').source||'Astra Pro');healthCard('esc',es,bool(raw('connected.esc_feedback'))?'F103 ACK fresh via F411':'F411 → F103 VESC gateway');healthCard('localization',loc,textish(obj('localization_state').state||obj('localization_state').raw||'waiting'));healthCard('nav2',nv,bool(raw('system.nav2_ready'))?'planner/controller ready':'waiting gates');healthCard('hmi',hm,`${raw('hmi_page')||'--'} • ${raw('hmi_mode')||'--'}`);healthCard('joystick',joy,joy==='ok'?`${js.state||'CONNECTED'} • telemetry only`:'DISCONNECTED • tidak menutup gate');renderDataHealth()}
  {const ct=obj('cmd_teleop'),cp=obj('cmd_pre_smoother'),cs=obj('cmd_autonomy_integrated'),cf=obj('cmd_final'),caa=obj('cmd_actuator'),mux=getPath(obj('nav_cmd_mux'),'raw')||'IDLE',input=String(mux).startsWith('TELEOP')?ct:cs;setText('pipeInputLabel',`Selected input • ${mux}`);setText('pipeNav',fmt(input.linear_x));setText('pipeSafety',fmt(cp.linear_x));setText('pipeFinal',fmt(cf.linear_x));setText('pipeActuator',fmt(caa.linear_x));history.push({t:Date.now(),nav:+input.linear_x||0,final:+cf.linear_x||0,actual:+raw('esc_drive_actual')||0});while(history.length>180)history.shift();drawSpark();renderAuthority()}
  {renderAlerts();renderEventTimeline()}
