function addRuntimeEvent(kind,value,severity='info',meta={}){
  const atMs=Date.now(),origin=recordStartedMs||chartEpochMs,analysisTime=Math.max(0,(atMs-origin)/1000),input={timestamp_ms:atMs,severity,domain:meta.domain||'system',layer:meta.layer||'runtime',source:meta.source||'ros_web',code:meta.code||String(kind).toUpperCase().replace(/[^A-Z0-9]+/g,'_'),summary:kind,state:value,related_channels:meta.related_channels||[],related_evidence:meta.related_evidence||[],analysis_time_s:analysisTime},e=window.AGVDiagnostics?.normalizeEvent(input)||{...input,atMs,kind,value:String(value),text:`${kind}: ${value}`,severity_css:severity==='danger'?'danger':severity==='warn'?'warn':'info'};
  eventLog.push(e);while(eventLog.length>240)eventLog.shift();if(activePage==='overview')renderEventTimeline()
}
function watchRuntimeEvent(key,value,label,severity='info',meta={}){const norm=String(value??'--');if(!eventLast.has(key)){eventLast.set(key,norm);return}if(eventLast.get(key)===norm)return;eventLast.set(key,norm);addRuntimeEvent(label,norm,severity,meta)}
function trackRuntimeEvents(){
  const tool=obj('vesc_tool_status');
  watchRuntimeEvent('goal',getPath(obj('goal_state'),'state')||'IDLE','GOAL','info',{domain:'navigation',layer:'mission',source:'goal_state',related_channels:['goal_state']});
  watchRuntimeEvent('esc_mux',getPath(obj('esc_mux'),'raw')||'IDLE','ESC AUTHORITY','info',{domain:'esc',layer:'authority',source:'esc_mux',related_channels:['esc_mux']});
  watchRuntimeEvent('nav_mux',getPath(obj('nav_cmd_mux'),'raw')||'IDLE','NAV MUX','info',{domain:'navigation',layer:'control',source:'nav_cmd_mux',related_channels:['nav_cmd_mux','cmd_final']});
  watchRuntimeEvent('motion',bool(raw('system.motion_ready'))?'OPEN':'LOCKED','MOTION GATE',bool(raw('system.motion_ready'))?'info':'warn',{domain:'system',layer:'safety',source:'system.motion_ready',related_channels:['system.motion_ready']});
  watchRuntimeEvent('estop',bool(raw('system.estop'))?'ACTIVE':'CLEAR','E-STOP',bool(raw('system.estop'))?'danger':'info',{domain:'system',layer:'hardware_safety',source:'system.estop',related_channels:['system.estop']});
  watchRuntimeEvent('perception_emergency',bool(raw('perception_emergency'))?'ACTIVE':'CLEAR','PERCEPTION EMERGENCY',bool(raw('perception_emergency'))?'danger':'info',{domain:'perception',layer:'safety',source:'perception_emergency',related_channels:['perception_emergency','trajectory_safety_state']});
  watchRuntimeEvent('gnss',bool(raw('connected.gnss'))?'CONNECTED':'OFFLINE','GNSS',bool(raw('connected.gnss'))?'info':'warn',{domain:'navigation',layer:'sensor',source:'connected.gnss',related_channels:['connected.gnss','gnss_quality']});
  watchRuntimeEvent('hmi',bool(raw('connected.hmi'))?'CONNECTED':'OFFLINE','F4 HMI',bool(raw('connected.hmi'))?'info':'warn',{domain:'system',layer:'transport',source:'connected.hmi',related_channels:['connected.hmi','hmi_page','hmi_mode']});
  watchRuntimeEvent('vesc_transport',bool(raw('connected.vesc_transport'))?'CONNECTED':'OFFLINE','F411-F103 TRANSPORT',bool(raw('connected.vesc_transport'))?'info':'danger',{domain:'esc',layer:'transport',source:'vesc_transport_status',related_channels:['connected.vesc_transport','vesc_transport_status','vesc_transport_error']});
  watchRuntimeEvent('vesc_owner',tool.owner||tool.mode||'--','VESC OWNER','info',{domain:'esc',layer:'authority',source:'vesc_tool_status',related_channels:['vesc_tool_status']})
}
function renderEventTimeline(){
  const box=$('eventTimeline');if(!box)return;const rows=eventLog.slice(-40).reverse();
  box.innerHTML=rows.length?rows.map(e=>{const idx=eventLog.indexOf(e),sev=String(e.severity||'INFO'),css=e.severity_css||(sev==='CRITICAL'||sev==='ERROR'?'danger':sev==='WARNING'?'warn':'info');return `<div class="event-row event-${css}" role="button" tabindex="0" data-event-index="${idx}" title="${escapeHtml(`${e.domain||'system'} / ${e.layer||'runtime'} / ${e.source||'--'}`)}"><time>${new Date(e.timestamp_ms||e.atMs).toLocaleTimeString('id-ID',{hour12:false})}</time><b>${escapeHtml(e.summary||e.kind||e.code)}</b><span>${escapeHtml(e.state??e.value??'')} <small>${escapeHtml(sev)}</small></span></div>`}).join(''):'<div class="empty-state">No runtime events yet.</div>';
  const open=row=>{const e=eventLog[+row.dataset.eventIndex];if(!e)return;window.analysisSession?.selectEvent(e);row.classList.add('selected');setTimeout(()=>row.classList.remove('selected'),900)};
  qa('[data-event-index]',box).forEach(row=>{row.onclick=()=>open(row);row.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open(row)}}})
}
function renderAlerts(){const a=[];if(bool(raw('system.estop')))a.push(['danger','Emergency stop ACTIVE']);if(bool(raw('perception_emergency')))a.push(['danger','Perception emergency stop ACTIVE']);if(!bool(raw('connected.esc_feedback')))a.push(['danger','ESC ACK belum fresh — motor command tidak dianggap ready']);if(!bool(raw('connected.gnss')))a.push(['warn','GNSS belum connected']);if(!bool(raw('connected.imu')))a.push(['warn','IMU belum connected']);if(!bool(raw('system.motion_ready')))a.push(['warn','Motion gate masih tertutup']);if(bool(raw('system.motion_ready'))&&bool(raw('connected.esc_feedback')))a.push(['ok','Core motion chain ready']);setText('alertCount',a.filter(x=>x[0]!=='ok').length);$('alerts').innerHTML=a.length?a.map(x=>`<div class="alert-item ${x[0]}">${escapeHtml(x[1])}</div>`).join(''):'<div class="empty-state">Tidak ada kondisi aktif.</div>'}
function drawSpark(){const c=$('speedSpark'),ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);const css=getComputedStyle(document.body);ctx.strokeStyle=css.getPropertyValue('--border2');ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,h/2);ctx.lineTo(w,h/2);ctx.stroke();if(history.length<2)return;const max=Math.max(1,...history.flatMap(x=>[Math.abs(x.nav),Math.abs(x.final),Math.abs(x.actual)]));[['nav','--blue'],['final','--green'],['actual','--cyan']].forEach(([key,col])=>{ctx.strokeStyle=css.getPropertyValue(col);ctx.lineWidth=2;ctx.beginPath();history.forEach((p,i)=>{const x=i/(history.length-1)*w,y=h/2-(p[key]/max)*(h*.38);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()})}
